def first_unique_index(s):
    from collections import Counter
    counts=Counter(s)
    return next((i for i,ch in enumerate(s) if counts[ch]==1),-1)

def edit_distance(a,b):
    prev=list(range(len(b)+1))
    for i,x in enumerate(a,1):
        cur=[i]
        for j,y in enumerate(b,1):
            cur.append(min(prev[j]+1,cur[-1]+1,prev[j-1]+(x!=y)))
        prev=cur
    return prev[-1]

def count_islands(grid):
    if not grid or not grid[0]: return 0
    h,w=len(grid),len(grid[0])
    seen=set()
    count=0
    for y in range(h):
        for x in range(w):
            if grid[y][x]!='1' or (y,x) in seen: continue
            count+=1
            stack=[(y,x)]
            seen.add((y,x))
            while stack:
                cy,cx=stack.pop()
                for ny,nx in ((cy-1,cx),(cy+1,cx),(cy,cx-1),(cy,cx+1)):
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]=='1' and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
    return count

def merge_counts(items):
    out={}
    for item in items:
        for key,value in item.items(): out[key]=out.get(key,0)+value
    return out

def decode_rle(s):
    out=[]
    i=0
    while i<len(s):
        ch=s[i]
        i+=1
        j=i
        while i<len(s) and s[i].isdigit(): i+=1
        out.append(ch*int(s[j:i]))
    return ''.join(out)

def lcm_many(a):
    import math
    result=1
    for x in a:
        result=abs(result*x)//math.gcd(result,x) if result and x else 0
    return result

def flatten_dict(d):
    out={}
    def visit(value,prefix):
        for key,item in value.items():
            path=prefix+'.'+key if prefix else key
            if isinstance(item,dict): visit(item,path)
            else: out[path]=item
    visit(d,'')
    return out
